select date_trunc('quarter', launch_date) as quarter_start, date_trunc('week', launch_date) as week_start, sum(price) filter (where category = 'Home') as home_total_price, count(*) filter (where brand = 'Stark') as stark_rows, round(sum(stock_qty) / nullif(count(case when brand = 'Umbrella' then 1 end), 0), 2) as stock_qty_per_umbrella, count(distinct brand) as distinct_brands from products group by cube (date_trunc('quarter', launch_date), date_trunc('week', launch_date)) order by stark_rows desc nulls first;
